// Guard against missing or malformed file input from the form
const binaryData = items[0].binary;
const fileKey = "CV_Upload";

if (!binaryData || !binaryData[fileKey]) {
  throw new Error("No CV file uploaded");
}

const file = binaryData[fileKey];

const allowedTypes = {
  "application/pdf": "pdf",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
};

if (!allowedTypes[file.mimeType]) {
  throw new Error("Invalid file format. Only PDF and DOCX allowed.");
}

const maxSize = 5 * 1024 * 1024; // 5MB
if (file.fileSize && file.fileSize > maxSize) {
  throw new Error("File too large. Max size is 5MB.");
}

// Validate and build candidate name from form fields
const firstName = items[0].json["First Name"];
const surname = items[0].json["Surname"];

if (!firstName || !surname) {
  throw new Error("First name or surname missing from form submission");
}

const fullName = `${firstName} ${surname}`;

// Build a predictable storage path for Supabase
const extension = allowedTypes[file.mimeType];
const datePrefix = new Date().toISOString().split("T")[0];

// Normalize name for filesystem safety
const safeName = fullName
  .trim()
  .replace(/\s+/g, "_")
  .replace(/[^a-zA-Z0-9_]/g, "");

items[0].json.full_name = fullName;
items[0].json.storage_path = `${datePrefix}/${safeName}_CV.${extension}`;

return items;

